//! tpt-media-sys — FFI bridge exposing safe tpt-media APIs to C, C++,
//! Python (via cffi), and Node.js (via napi-rs).
//!
//! All public items are `extern "C"` and `#[no_mangle]`. The matching
//! C header (`tpt_media.h`) is generated by `cbindgen`; see
//! `crates/tpt-media-sys/cbindgen.toml`.

#![allow(unsafe_code)]
#![allow(non_camel_case_types)]

#[repr(C)]
pub struct tpt_demuxer { _private: [u8; 0] }

#[repr(C)]
pub struct tpt_decoder { _private: [u8; 0] }

/// FFI-safe error codes.
#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum tpt_status {
    TPT_OK = 0,
    TPT_ERR_INVALID_ARG = 1,
    TPT_ERR_INVALID_MAGIC = 3,
    TPT_ERR_UNSUPPORTED_VERSION = 4,
    TPT_ERR_MALFORMED = 5,
    TPT_ERR_TRUNCATED = 6,
    TPT_ERR_INTERNAL = 99,
}

#[no_mangle]
pub extern "C" fn tpt_version_major() -> u32 {
    env!("CARGO_PKG_VERSION_MAJOR").parse().unwrap_or(0)
}

#[no_mangle]
pub extern "C" fn tpt_version_minor() -> u32 {
    env!("CARGO_PKG_VERSION_MINOR").parse().unwrap_or(0)
}

#[no_mangle]
pub extern "C" fn tpt_version_patch() -> u32 {
    env!("CARGO_PKG_VERSION_PATCH").parse().unwrap_or(0)
}